tId\",\n          \"available\"\n        ]\n      },\n      \"Circle\": {\n        \"type\": \"object\",\n        \"additionalProperties\": false,\n        \"properties\": {\n          \"id\": {\n            \"type\": \"string\",\n            \"format\": \"uuid\"\n          },\n          \"version\": {\n            \"type\": \"integer\",\n            \"minimum\": 1\n          },\n          \"createdAt\": {\n            \"type\": \"string\",\n            \"format\": \"date-time\"\n          },\n          \"updatedAt\": {\n            \"type\": \"string\",\n            \"format\": \"date-time\"\n          },\n          \"name\": {\n            \"type\": \"string\",\n            \"maxLength\": 60\n          },\n          \"description\": {\n            \"type\": \"string\",\n            \"maxLength\": 300\n          },\n          \"role\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"owner\",\n              \"admin\",\n              \"member\"\n            ]\n          },\n          \"memberCount\": {\n            \"type\": \"integer\",\n            \"minimum\": 0\n          },\n          \"status\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"active\",\n              \"archived\"\n            ]\n          }\n        },\n        \"required\": [\n          \"id\",\n          \"version\",\n          \"createdAt\",\n          \"updatedAt\",\n          \"name\",\n          \"role\",\n          \"memberCount\",\n          \"status\"\n        ]\n      },\n      \"CircleWrite\": {\n        \"type\": \"object\",\n        \"additionalProperties\": false,\n        \"properties\": {\n          \"name\": {\n            \"type\": \"string\",\n            \"minLength\": 1,\n            \"maxLength\": 60\n          },\n          \"description\": {\n            \"type\": \"string\",\n            \"maxLength\": 300\n          }\n        },\n        \"required\": [\n          \"name\"\n        ]\n      },\n      \"Memb