        append("ed\": [\n          \"id\",\n          \"version\",\n          \"createdAt\",\n          \"updatedAt\",\n          \"user\",\n          \"role\",\n          \"status\"\n        ]\n      },\n      \"MemberPatch\": {\n        \"type\": \"object\",\n        \"additionalProperties\": false,\n        \"properties\": {\n          \"role\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"admin\",\n              \"member\"\n            ]\n          }\n        },\n        \"required\": [\n          \"role\"\n        ]\n      },\n      \"InvitationRequest\": {\n        \"type\": \"object\",\n        \"additionalProperties\": false,\n        \"properties\": {\n          \"targetType\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"circle\",\n              \"household\",\n              \"pact\",\n              \"potluck\"\n            ]\n          },\n          \"targetId\": {\n            \"type\": \"string\",\n            \"format\": \"uuid\"\n          },\n          \"expiresInHours\": {\n            \"type\": \"integer\",\n            \"minimum\": 1\n          },\n          \"maxUses\": {\n            \"type\": \"integer\",\n            \"minimum\": 1\n          }\n        },\n        \"required\": [\n          \"targetType\",\n          \"targetId\"\n        ]\n      },\n      \"Invitation\": {\n        \"type\": \"object\",\n        \"additionalProperties\": false,\n        \"properties\": {\n          \"id\": {\n            \"type\": \"string\",\n            \"format\": \"uuid\"\n          },\n          \"version\": {\n            \"type\": \"integer\",\n            \"minimum\": 1\n          },\n          \"createdAt\": {\n            \"type\": \"string\",\n            \"format\": \"date-time\"\n          },\n          \"updatedAt\": {\n            \"type\": \"string\",\n            \"format\": \"date-time\"\n          },\n          \"targetType\": {\n            \"type\": \"string\",\n       